mapper.sql:
FROM platform_content c JOIN platform_connection pc ON pc.id=c.connection_id JOIN platform_account a ON a.id=pc.platform_account_id JOIN platform p ON p.id=a.platform_id WHERE 1=1
    AND a.creator_id=#{creatorId}
    AND c.connection_id=#{connectionId}
    AND p.code=#{platformCode}
    AND (c.title LIKE CONCAT('%',#{q},'%') OR c.description LIKE CONCAT('%',#{q},'%'))
